import math
from itertools import permutations

def sum_of_divisors(m):
    """Calculates sigma(m), the sum of all divisors of m."""
    if m <= 0:
        return 0
    s = 0
    for i in range(1, int(math.sqrt(m)) + 1):
        if m % i == 0:
            s += i
            if i * i != m:
                s += m // i
    return s

def is_perfect_square(n):
    """Checks if n is a perfect square."""
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

def find_divisors(m):
    """Finds all divisors of m."""
    divs = []
    for i in range(1, int(math.sqrt(m)) + 1):
        if m % i == 0:
            divs.append(i)
            if i * i != m:
                divs.append(m // i)
    return sorted(divs)

def check_permutation(divisors):
    """
    Checks if there exists a permutation of divisors such that all prefix sums are squares.
    Uses backtracking search.
    """
    n = len(divisors)
    divs_set = set(divisors)

    def backtrack(current_sum, used_divisors, path):
        if len(path) == n:
            # We already ensured sigma(m) is a square, so the last sum is good.
            return True

        for d in divisors:
            if d not in used_divisors:
                next_sum = current_sum + d
                if is_perfect_square(next_sum):
                    # If the next sum is a square, try this path
                    used_divisors.add(d)
                    path.append(d)
                    if backtrack(next_sum, used_divisors, path):
                        return True
                    # Backtrack
                    path.pop()
                    used_divisors.remove(d)
        return False

    # The first element a1 must be a perfect square itself.
    for start_d in divisors:
        if is_perfect_square(start_d):
            used = {start_d}
            path = [start_d]
            if backtrack(start_d, used, path):
                return True

    return False

