import math
from itertools import permutations

def get_divisors(n):
    """Returns a sorted list of all divisors of n."""
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def solve_permutation_problem(m, divisors):
    """
    Attempts to find a permutation of divisors such that all prefix sums are squares.
    Uses recursive backtracking.
    Returns True if a solution is found, False otherwise.
    """
    n = len(divisors)

    # 1. Identify possible starting points (a1 must be a square divisor)
    square_divisors = [d for d in divisors if math.isqrt(d)**2 == d]

    if not square_divisors:
        return False

    # Use a set to track available divisors by their value
    # We use a recursive helper function to manage state (current sum, used divisors)

    def backtrack(current_sum, used_mask):
        # Base Case: All divisors have been used
        if used_mask == (1 << n) - 1:
            # We must check if the final sum is a perfect square, 
            # but since we filtered candidates based on sigma(m) being a square, 
            # this is guaranteed if the construction succeeded up to n-1.
            return True

        # Recursive step: Try adding every unused divisor
        for i in range(n):
            if not (used_mask & (1 << i)):
                a_i = divisors[i]
                next_sum = current_sum + a_i

                # Constraint Check: The new partial sum must be a perfect square
                if math.isqrt(next_sum)**2 == next_sum:
                    # If it is a square, proceed to the next step
                    if backtrack(next_sum, used_mask | (1 << i)):
                        return True

        return False

    # Try every valid starting divisor a1
    for i in range(n):
        a1 = divisors[i]
        if math.isqrt(a1)**2 == a1:
            # Start the search from the first step
            if backtrack(a1, 1 << i):
                return True

    return False


